from hashlib import sha1 as _sha1

def sha1(path):
    h = _sha1()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(1 << 20), b""):
            h.update(b)
    return h.hexdigest()

GEN, INTEN = os.path.join(UP, "ckpt", "gen.ckpt"), os.path.join(UP, "ckpt", "inten.ckpt")
